UPDATE `payroll_journal_lines` c JOIN payroll_journals j ON j.id = c.journal_id JOIN legacy_id_map m ON m.legacy_id = c.`source_id` AND m.table_name = CASE WHEN j.journal_type = 'PAYROLL_ACCRUAL' THEN IF(c.employee_id IS NOT NULL, 'payroll_employee_results', 'payroll_runs') WHEN j.journal_type IN ('PAYMENT_SETTLEMENT','PAYMENT_REVERSAL') THEN 'payroll_payment_items' END SET c.`source_id_new` = m.new_id;
