-- ======================================================================== M6P
-- journal-line source discriminator (explicit, M6): the entity a line's source_id points to. Backfilled with the
-- Stage-1 rule (accrual: EMPLOYEE-grouped line -> PAYROLL_RESULT, else PAYROLL_RUN; settlement / reversal ->
-- PAYMENT_ITEM) and then proven against the CUID's own table in legacy_id_map (ground truth, CUIDs are global).
ALTER TABLE payroll_journal_lines ADD COLUMN source_entity ENUM('PAYROLL_RUN','PAYROLL_RESULT','PAYMENT_ITEM') NULL AFTER source_id_new;
UPDATE payroll_journal_lines l JOIN payroll_journals j ON j.id = l.journal_id SET l.source_entity = CASE WHEN l.source_id IS NULL THEN NULL WHEN j.journal_type = 'PAYROLL_ACCRUAL' THEN IF(l.employee_id IS NOT NULL, 'PAYROLL_RESULT', 'PAYROLL_RUN') WHEN j.journal_type IN ('PAYMENT_SETTLEMENT', 'PAYMENT_REVERSAL') THEN 'PAYMENT_ITEM' END;
-- payroll approval canonical form version: NULL = v1 (CUID canonical, historical hashes stay as they are)
ALTER TABLE payroll_runs ADD COLUMN approval_canonical_version INT NULL AFTER approval_snapshot_hash;
SELECT 'check', 'M6P: every non-null line source has a discriminator', IF((SELECT COUNT(*) FROM payroll_journal_lines WHERE (source_id IS NULL) <> (source_entity IS NULL)) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
SELECT 'check', 'M6P: discriminator = the own table of the CUID (legacy_id_map)', IF((SELECT COUNT(*) FROM payroll_journal_lines l JOIN legacy_id_map m ON m.legacy_id = l.source_id WHERE m.table_name <> CASE l.source_entity WHEN 'PAYROLL_RUN' THEN 'payroll_runs' WHEN 'PAYROLL_RESULT' THEN 'payroll_employee_results' WHEN 'PAYMENT_ITEM' THEN 'payroll_payment_items' END) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
SELECT 'check', 'M6P: every line source is in legacy_id_map', IF((SELECT COUNT(*) FROM payroll_journal_lines l LEFT JOIN legacy_id_map m ON m.legacy_id = l.source_id WHERE l.source_id IS NOT NULL AND m.legacy_id IS NULL) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
SELECT 'check', 'M6P: source_id_new resolves through the discriminator to the same CUID', IF((SELECT COUNT(*) FROM payroll_journal_lines l LEFT JOIN legacy_id_map m ON m.new_id = l.source_id_new AND m.table_name = CASE l.source_entity WHEN 'PAYROLL_RUN' THEN 'payroll_runs' WHEN 'PAYROLL_RESULT' THEN 'payroll_employee_results' WHEN 'PAYMENT_ITEM' THEN 'payroll_payment_items' END WHERE l.source_id IS NOT NULL AND NOT (BINARY m.legacy_id <=> BINARY l.source_id)) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
SELECT 'M6P done', COUNT(*), SUM(source_entity IS NOT NULL) FROM payroll_journal_lines;
