SELECT 'check', 'notification links carry at most one CUID', IF((SELECT COUNT(*) FROM notifications WHERE REGEXP_LIKE(link, 'c[a-z0-9]{24}.*c[a-z0-9]{24}', 'c')) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
SELECT 'check', 'every CUID in a link resolves', IF((SELECT COUNT(*) FROM notifications n LEFT JOIN legacy_id_map m ON m.legacy_id = REGEXP_SUBSTR(n.link, 'c[a-z0-9]{24}', 1, 1, 'c') WHERE REGEXP_LIKE(n.link, 'c[a-z0-9]{24}', 'c') AND m.legacy_id IS NULL) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
SELECT 'check', 'every link CUID belongs to the table of its route', IF((SELECT COUNT(*) FROM notifications n JOIN legacy_id_map m ON m.legacy_id = REGEXP_SUBSTR(n.link, 'c[a-z0-9]{24}', 1, 1, 'c') WHERE NOT (m.table_name <=> CASE WHEN REGEXP_LIKE(n.link, '^/app/approvals/', 'c') THEN 'approval_instances' WHEN REGEXP_LIKE(n.link, '^/app/my-leave\\?focus=', 'c') THEN 'leave_requests' WHEN REGEXP_LIKE(n.link, '^/app/my-overtime\\?focus=', 'c') THEN 'overtime_requests' WHEN REGEXP_LIKE(n.link, '^/app/my-attendance\\?focus=', 'c') THEN 'attendance_correction_requests' WHEN REGEXP_LIKE(n.link, '^/app/my-payslips/', 'c') THEN 'payslips' WHEN REGEXP_LIKE(n.link, '^/app/payroll/runs/', 'c') THEN 'payroll_runs' END)) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
SELECT 'check', 'every link is a known route', IF((SELECT COUNT(*) FROM notifications n WHERE n.link IS NOT NULL AND n.link <> '/app/my-payments' AND CASE WHEN REGEXP_LIKE(n.link, '^/app/approvals/', 'c') THEN 'approval_instances' WHEN REGEXP_LIKE(n.link, '^/app/my-leave\\?focus=', 'c') THEN 'leave_requests' WHEN REGEXP_LIKE(n.link, '^/app/my-overtime\\?focus=', 'c') THEN 'overtime_requests' WHEN REGEXP_LIKE(n.link, '^/app/my-attendance\\?focus=', 'c') THEN 'attendance_correction_requests' WHEN REGEXP_LIKE(n.link, '^/app/my-payslips/', 'c') THEN 'payslips' WHEN REGEXP_LIKE(n.link, '^/app/payroll/runs/', 'c') THEN 'payroll_runs' END IS NULL) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));

