UPDATE `leave_request_days` c SET c.`active_key` = (SELECT GROUP_CONCAT(COALESCE(CAST(mm.new_id AS CHAR), tk.tok) ORDER BY tk.pos SEPARATOR ':') FROM JSON_TABLE(CONCAT('["', REPLACE(c.`active_key`, ':', '","'), '"]'), '$[*]' COLUMNS (pos FOR ORDINALITY, tok VARCHAR(191) PATH '$')) tk LEFT JOIN legacy_id_map mm ON mm.legacy_id = tk.tok COLLATE utf8mb4_unicode_ci) WHERE c.`active_key` IS NOT NULL;
UPDATE `overtime_requests` c SET c.`active_key` = (SELECT GROUP_CONCAT(COALESCE(CAST(mm.new_id AS CHAR), tk.tok) ORDER BY tk.pos SEPARATOR ':') FROM JSON_TABLE(CONCAT('["', REPLACE(c.`active_key`, ':', '","'), '"]'), '$[*]' COLUMNS (pos FOR ORDINALITY, tok VARCHAR(191) PATH '$')) tk LEFT JOIN legacy_id_map mm ON mm.legacy_id = tk.tok COLLATE utf8mb4_unicode_ci) WHERE c.`active_key` IS NOT NULL;
UPDATE `attendance_correction_requests` c SET c.`pending_key` = (SELECT GROUP_CONCAT(COALESCE(CAST(mm.new_id AS CHAR), tk.tok) ORDER BY tk.pos SEPARATOR ':') FROM JSON_TABLE(CONCAT('["', REPLACE(c.`pending_key`, ':', '","'), '"]'), '$[*]' COLUMNS (pos FOR ORDINALITY, tok VARCHAR(191) PATH '$')) tk LEFT JOIN legacy_id_map mm ON mm.legacy_id = tk.tok COLLATE utf8mb4_unicode_ci) WHERE c.`pending_key` IS NOT NULL;
UPDATE `approval_workflows` c SET c.`active_key` = (SELECT GROUP_CONCAT(COALESCE(CAST(mm.new_id AS CHAR), tk.tok) ORDER BY tk.pos SEPARATOR ':') FROM JSON_TABLE(CONCAT('["', REPLACE(c.`active_key`, ':', '","'), '"]'), '$[*]' COLUMNS (pos FOR ORDINALITY, tok VARCHAR(191) PATH '$')) tk LEFT JOIN legacy_id_map mm ON mm.legacy_id = tk.tok COLLATE utf8mb4_unicode_ci) WHERE c.`active_key` IS NOT NULL;
UPDATE `payroll_journal_sources` c SET c.`active_key` = (SELECT GROUP_CONCAT(COALESCE(CAST(mm.new_id AS CHAR), tk.tok) ORDER BY tk.pos SEPARATOR ':') FROM JSON_TABLE(CONCAT('["', REPLACE(c.`active_key`, ':', '","'), '"]'), '$[*]' COLUMNS (pos FOR ORDINALITY, tok VARCHAR(191) PATH '$')) tk LEFT JOIN legacy_id_map mm ON mm.legacy_id = tk.tok COLLATE utf8mb4_unicode_ci) WHERE c.`active_key` IS NOT NULL;
UPDATE `saved_report_filters` c SET c.`default_key` = (SELECT GROUP_CONCAT(COALESCE(CAST(mm.new_id AS CHAR), tk.tok) ORDER BY tk.pos SEPARATOR ':') FROM JSON_TABLE(CONCAT('["', REPLACE(c.`default_key`, ':', '","'), '"]'), '$[*]' COLUMNS (pos FOR ORDINALITY, tok VARCHAR(191) PATH '$')) tk LEFT JOIN legacy_id_map mm ON mm.legacy_id = tk.tok COLLATE utf8mb4_unicode_ci) WHERE c.`default_key` IS NOT NULL;
UPDATE `notifications` c SET c.`dedupe_key` = (SELECT GROUP_CONCAT(COALESCE(CAST(mm.new_id AS CHAR), tk.tok) ORDER BY tk.pos SEPARATOR ':') FROM JSON_TABLE(CONCAT('["', REPLACE(c.`dedupe_key`, ':', '","'), '"]'), '$[*]' COLUMNS (pos FOR ORDINALITY, tok VARCHAR(191) PATH '$')) tk LEFT JOIN legacy_id_map mm ON mm.legacy_id = tk.tok COLLATE utf8mb4_unicode_ci) WHERE c.`dedupe_key` IS NOT NULL;
UPDATE notifications n JOIN legacy_id_map m ON m.legacy_id = REGEXP_SUBSTR(n.link, 'c[a-z0-9]{24}', 1, 1, 'c') SET n.link = REPLACE(n.link, m.legacy_id, CAST(m.new_id AS CHAR)) WHERE n.link IS NOT NULL;
