SELECT 'check', 'overtime_requests.active_key = numeric formula', IF((SELECT COUNT(*) FROM `overtime_requests` WHERE `active_key` IS NOT NULL AND BINARY `active_key` <> BINARY CONCAT(employee_id, ':', DATE_FORMAT(work_date, '%Y-%m-%d'), ':', type)) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
SELECT 'check', 'attendance_correction_requests.pending_key = numeric formula', IF((SELECT COUNT(*) FROM `attendance_correction_requests` WHERE `pending_key` IS NOT NULL AND BINARY `pending_key` <> BINARY CONCAT(employee_id, ':', DATE_FORMAT(work_date, '%Y-%m-%d'))) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
SELECT 'check', 'approval_workflows.active_key = numeric formula', IF((SELECT COUNT(*) FROM `approval_workflows` WHERE `active_key` IS NOT NULL AND BINARY `active_key` <> BINARY CONCAT(company_id, ':', target_type)) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
SELECT 'check', 'payroll_journal_sources.active_key = numeric formula', IF((SELECT COUNT(*) FROM `payroll_journal_sources` WHERE `active_key` IS NOT NULL AND BINARY `active_key` <> BINARY CONCAT(CASE source_type WHEN 'PAYROLL_RUN' THEN 'ACCRUAL' WHEN 'PAYMENT_ITEM' THEN 'SETTLEMENT' WHEN 'PAYMENT_REVERSAL' THEN 'REVERSAL' END, ':', source_id)) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
SELECT 'check', 'saved_report_filters.default_key = numeric formula', IF((SELECT COUNT(*) FROM `saved_report_filters` WHERE `default_key` IS NOT NULL AND BINARY `default_key` <> BINARY CONCAT(user_id, ':', report_type)) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
