SELECT 'check', 'no CUID left in keys / links / notification metadata / saved filters', IF(((SELECT COUNT(*) FROM `leave_request_days` WHERE REGEXP_LIKE(`active_key`, 'c[a-z0-9]{24}', 'c')) + (SELECT COUNT(*) FROM `overtime_requests` WHERE REGEXP_LIKE(`active_key`, 'c[a-z0-9]{24}', 'c')) + (SELECT COUNT(*) FROM `attendance_correction_requests` WHERE REGEXP_LIKE(`pending_key`, 'c[a-z0-9]{24}', 'c')) + (SELECT COUNT(*) FROM `approval_workflows` WHERE REGEXP_LIKE(`active_key`, 'c[a-z0-9]{24}', 'c')) + (SELECT COUNT(*) FROM `payroll_journal_sources` WHERE REGEXP_LIKE(`active_key`, 'c[a-z0-9]{24}', 'c')) + (SELECT COUNT(*) FROM `saved_report_filters` WHERE REGEXP_LIKE(`default_key`, 'c[a-z0-9]{24}', 'c')) + (SELECT COUNT(*) FROM `notifications` WHERE REGEXP_LIKE(`dedupe_key`, 'c[a-z0-9]{24}', 'c')) + (SELECT COUNT(*) FROM notifications WHERE REGEXP_LIKE(link, 'c[a-z0-9]{24}', 'c') OR REGEXP_LIKE(CAST(metadata_json AS CHAR), 'c[a-z0-9]{24}', 'c')) + (SELECT COUNT(*) FROM saved_report_filters WHERE REGEXP_LIKE(CAST(filters_json AS CHAR), 'c[a-z0-9]{24}', 'c'))) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));
SELECT 'check', 'every numeric link resolves in the table of its route', IF((SELECT COUNT(*) FROM notifications n LEFT JOIN legacy_id_map m ON m.new_id = CAST(REGEXP_SUBSTR(n.link, '[0-9]+$') AS UNSIGNED) AND m.table_name = CASE WHEN REGEXP_LIKE(n.link, '^/app/approvals/', 'c') THEN 'approval_instances' WHEN REGEXP_LIKE(n.link, '^/app/my-leave\\?focus=', 'c') THEN 'leave_requests' WHEN REGEXP_LIKE(n.link, '^/app/my-overtime\\?focus=', 'c') THEN 'overtime_requests' WHEN REGEXP_LIKE(n.link, '^/app/my-attendance\\?focus=', 'c') THEN 'attendance_correction_requests' WHEN REGEXP_LIKE(n.link, '^/app/my-payslips/', 'c') THEN 'payslips' WHEN REGEXP_LIKE(n.link, '^/app/payroll/runs/', 'c') THEN 'payroll_runs' END WHERE n.link IS NOT NULL AND n.link <> '/app/my-payments' AND m.legacy_id IS NULL) = 0, 'ok', (SELECT 1 UNION ALL SELECT 2));

